function openCalibration(){navigationLog("Opening calibration setup…");headPositionScreen.hidden=true;calibrationSetup.hidden=false;gazeDot.hidden=true;setStep("calibration");console.info("[OpenEyeTrack navigation] calibrationSetup.hidden =",calibrationSetup.hidden);}
function openDemo(){demoScreen.hidden=false;gazeDot.hidden=false;setStep("demo");renderDemoItem("images");renderDemoItem("text");renderDemoItem("video");selectStimulus("images");if(recording)void finishRecording("recording_stop");beginRecording();tracker.setTrial("demo-images-1");tracker.mark("demo_start");}
function selectStimulus(name:string){document.querySelectorAll<HTMLElement>("[data-panel]").forEach(p=>p.classList.toggle("active",p.dataset.panel===name));document.querySelectorAll<HTMLButtonElement>("[data-stimulus]").forEach(b=>b.classList.toggle("active",b.dataset.stimulus===name));if(recording){tracker.mark(`stimulus_${name}`);tracker.setTrial(`demo-${name}`);}}
async function finishDemo(){if(recording)await finishRecording("demo_end");demoScreen.hidden=true;gazeDot.hidden=true;demoResults.hidden=false;demoSampleCount.textContent=`${lastRecording.length} samples recorded`;heatmapFilter.value="all";renderHeatmap("all");}
function renderHeatmap(filter:string){const dpr=Math.min(devicePixelRatio||1,2),w=Math.max(600,Math.round(innerWidth*.82)),h=Math.max(360,Math.round(w*innerHeight/innerWidth));heatmap.width=w*dpr;heatmap.height=h*dpr;heatmap.style.aspectRatio=`${w}/${h}`;const ctx=heatmap.getContext("2d");if(!ctx)return;ctx.scale(dpr,dpr);ctx.fillStyle="#f8fafc";ctx.fillRect(0,0,w,h);const samples=lastRecording.filter(s=>(filter==="all"||s.trial===filter)&&s.gazeX!==null&&s.gazeY!==null);const sx=w/innerWidth,sy=h/innerHeight;for(const s of samples){const x=(s.gazeX as number)*sx,y=(s.gazeY as number)*sy,r=42;const g=ctx.createRadialGradient(x,y,0,x,y,r);g.addColorStop(0,"rgba(239,68,68,.10)");g.addColorStop(.45,"rgba(245,158,11,.055)");g.addColorStop(1,"rgba(59,130,246,0)");ctx.fillStyle=g;ctx.fillRect(x-r,y-r,r*2,r*2);}ctx.fillStyle="#64748b";ctx.font="14px system-ui";ctx.fillText(`${samples.length} valid gaze samples`,16,26);}

const demoImage=q<HTMLImageElement>("#demo-image"),demoImageCaption=q<HTMLElement>("#demo-image-caption"),demoReading=q<HTMLElement>("#demo-reading"),demoVideo=q<HTMLVideoElement>("#demo-video"),demoVideoCaption=q<HTMLElement>("#demo-video-caption");let demoIndices:Record<string,number>={images:0,text:0,video:0};
function renderDemoItem(kind:string){if(kind==="images"){const x=DEMO_IMAGES[demoIndices.images%DEMO_IMAGES.length];demoImage.src=x.src;demoImage.alt=x.caption;demoImageCaption.textContent=x.caption;}else if(kind==="text"){const x=DEMO_TEXTS[demoIndices.text%DEMO_TEXTS.length];demoReading.innerHTML=`<h3>${x.title}</h3><p class="stimulus-source">${x.source} · public-domain text</p>${x.body.map(p=>`<p>${p}</p>`).join("")}`;}else{const x=DEMO_VIDEOS[demoIndices.video%DEMO_VIDEOS.length];demoVideo.pause();demoVideo.src=x.src;demoVideoCaption.textContent=x.caption;demoVideo.load();}}
document.querySelectorAll<HTMLButtonElement>(".stimulus-prev,.stimulus-next").forEach(btn=>btn.onclick=()=>{const panel=btn.closest<HTMLElement>(".stimulus-panel"),kind=panel?.dataset.panel??"images",items=kind==="images"?DEMO_IMAGES:kind==="text"?DEMO_TEXTS:DEMO_VIDEOS,delta=btn.classList.contains("stimulus-next")?1:-1;demoIndices[kind]=(demoIndices[kind]+delta+items.length)%items.length;renderDemoItem(kind);tracker.mark(`demo_${kind}_${demoIndices[kind]+1}`);});renderDemoItem("images");renderDemoItem("text");renderDemoItem("video");

function saveCalibrationToBrowser(){try{const saved=calibration.exportSavedCalibration();if(saved){localStorage.setItem(CALIBRATION_STORAGE_KEY,JSON.stringify(saved));showSavedCalibration();}}catch(e){console.warn("Could not persist calibration",e);}}
function readSavedCalibration():SavedCalibration|null{try{const raw=localStorage.getItem(CALIBRATION_STORAGE_KEY);return raw?JSON.parse(raw) as SavedCalibration:null;}catch{return null;}}
function showSavedCalibration(){const saved=readSavedCalibration();savedCalibrationBanner.hidden=false;savedCalibrationTitle.textContent=saved?"Saved calibration available":"Browser calibration";savedCalibrationDetail.textContent=saved?`Saved ${new Date(saved.savedAt).toLocaleString()} · ${saved.config.featureModel} · ${saved.config.model.type}`:"No saved calibration yet. Complete calibration and validation to save it automatically on this browser.";useSavedCalibration.disabled=!saved;forgetSavedCalibration.disabled=!saved;}
useSavedCalibration.onclick=()=>{const saved=readSavedCalibration();if(!saved)return;try{calibration.restoreSavedCalibration(saved);const summary=calibration.calibrationSummary;if(summary)tracker.setCalibrationSummary(summary);showSavedCalibration();validateButton.disabled=false;demoButton.disabled=false;status.textContent="Saved calibration restored. Run validation to check accuracy before recording.";setStep("validation");}catch(e){status.textContent=e instanceof Error?e.message:String(e);}};
